import { type ComponentProps, type ReactNode } from "react";
import { cn } from "./utils";

type NotificationBadgeProps = Omit<ComponentProps<"span">, "children"> & {
    children: ReactNode;
    label: string;
    count?: number;
    max?: number;
    dot?: boolean;
    showZero?: boolean;
};

function NotificationBadge({
    children, label, count = 0, max = 99, dot = false, showZero = false,
    className, ...props
}: NotificationBadgeProps) {
    if (!label.trim() || !Number.isSafeInteger(count) || count < 0 ||
        !Number.isSafeInteger(max) || max < 1) {
        throw new RangeError(
            "NotificationBadge needs a label, non-negative count and positive max.",
        );
    }
    const visible = dot || count > 0 || showZero;
    return (
        <span {...props} data-ui="notification-badge"
            className={cn("relative inline-flex shrink-0 items-center gap-2 align-middle", className)}>
            {children}
            {visible && <>
                <span aria-hidden="true" data-slot="notification-count"
                    data-dot={dot || undefined} className={cn(
                        "pointer-events-none absolute right-0 top-0 " +
                        "flex -translate-y-1/3 translate-x-1/3 items-center " +
                        "justify-center rounded-full bg-accent font-semibold " +
                        "text-accent-foreground ring-2 ring-surface",
                        dot ? "size-2.5" : "min-h-5 min-w-5 px-1 text-[10px]",
                    )}>
                    {!dot && (count > max ? `${max}+` : count)}
                </span>
                <span className="sr-only">
                    {dot ? label : `${label} ${count}건`}
                </span>
            </>}
        </span>
    );
}

export { NotificationBadge };
export type { NotificationBadgeProps };
